                        当结果是false：a 引用指向的堆中的对象不是一个Cat类型的实例。
                2. 用法：
                    if(a instanceof Cat){
                        Cat c = (Cat)a;
                    }
         */

        /*Animal x = new Bird();
        if(x instanceof Cat) {
            Cat y = (Cat)x;
        }*/

        //T.t(new Cat());

        Cat temp = new Cat();
        T.t(temp);

        T.t(new Bird());

        // 关于JDK中 instanceof 运算符的改进。
        Animal x = new Bird();
        if(x instanceof Cat y) {
            y.catchMouse();
        }

